<?php
require __DIR__ . '/functions.php';
$lang = current_lang(); $locations = require __DIR__ . '/locations.php'; $lines = cart_products(); if (!$lines) { header('Location: index.php?view=cart'); exit; }
$subtotal = array_reduce($lines, fn($sum, $line) => $sum + $line['price'] * $line['quantity'], 0); $method = $_POST['delivery_method'] ?? 'À domicile'; $rates = ['Bureau' => 400, 'À domicile' => 700]; $shipping = $rates[$method] ?? 700; $error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') { check_csrf(); $required = ['full_name','phone','wilaya','commune']; foreach ($required as $field) if (trim($_POST[$field] ?? '') === '') $error = $lang === 'ar' ? 'يرجى ملء جميع الخانات.' : 'Please complete every delivery field.'; $captcha = $_POST['g-recaptcha-response'] ?? ''; global $config; if ($config['recaptcha_secret_key'] !== 'YOUR_RECAPTCHA_SECRET_KEY' && !$captcha) $error = 'Please complete the anti-bot check.'; if (!$error && $config['recaptcha_secret_key'] !== 'YOUR_RECAPTCHA_SECRET_KEY') { $verify = @file_get_contents('https://www.google.com/recaptcha/api/siteverify?secret=' . urlencode($config['recaptcha_secret_key']) . '&response=' . urlencode($captcha)); if (!$verify || !json_decode($verify, true)['success']) $error = 'Anti-bot verification failed.'; } if (!$error) { $statement = db()->prepare('INSERT INTO orders (full_name, phone, wilaya, commune, delivery_method, shipping_cost, total, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?)'); $statement->execute([trim($_POST['full_name']), trim($_POST['phone']), trim($_POST['wilaya']), trim($_POST['commune']), $method, $shipping, $subtotal + $shipping, 'New']); $orderId = db()->lastInsertId(); $item = db()->prepare('INSERT INTO order_items (order_id, product_id, quantity, unit_price) VALUES (?, ?, ?, ?)'); foreach ($lines as $line) { $item->execute([$orderId, $line['id'], $line['quantity'], $line['price']]); db()->prepare('UPDATE products SET stock = GREATEST(stock - ?, 0) WHERE id = ?')->execute([$line['quantity'], $line['id']]); } $_SESSION['cart'] = []; header('Location: checkout.php?success=' . $orderId . '&lang=' . $lang); exit; } }
?><!doctype html><html lang="<?= $lang ?>" dir="<?= $lang === 'ar' ? 'rtl' : 'ltr' ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= text('checkout') ?> | Lissi</title><link rel="stylesheet" href="style.css"><?php global $config; if ($config['recaptcha_site_key'] !== 'YOUR_RECAPTCHA_SITE_KEY'): ?><script src="https://www.google.com/recaptcha/api.js" async defer></script><?php endif; ?></head><body><header class="header shell"><a class="brand" href="index.php"><img src="assets/logo.jpeg" alt="Lissi"><span>LISSI</span></a><div class="header-tools"><a href="?lang=ar">ع</a><a href="?lang=fr">FR</a><a href="?lang=en">EN</a><button class="theme-toggle" type="button" data-theme-toggle>◐</button></div></header><main class="section shell"><?php if (isset($_GET['success'])): ?><div class="notice"><b><?= $lang === 'ar' ? 'تم استلام طلبك.' : 'Order received.' ?></b> <?= $lang === 'ar' ? 'سنتصل بك لتأكيد الطلب رقم' : 'We will call to confirm order' ?> #<?= e($_GET['success']) ?>.</div><a class="dark" href="index.php?lang=<?= $lang ?>"><?= text('shop') ?></a><?php else: ?><p class="eyebrow"><?= text('checkout') ?></p><h2><?= text('details') ?></h2><p><?= $lang === 'ar' ? 'سنتصل بك لتأكيد طلبك قبل الشحن.' : 'We will call to confirm your order before dispatch.' ?></p><?php if ($error): ?><div class="notice"><?= e($error) ?></div><?php endif; ?><form class="form" method="post"><input type="hidden" name="csrf" value="<?= csrf() ?>"><label><?= text('name') ?><input name="full_name" required></label><label><?= text('phone') ?><input name="phone" type="tel" required></label><div class="form-row"><label><?= text('wilaya') ?><select name="wilaya" id="wilaya" required><option value="">--</option><?php foreach ($locations as $id => $location): ?><option value="<?= $id ?>"><?= e($lang === 'ar' ? $location['ar'] : $location['fr']) ?></option><?php endforeach; ?></select></label><label><?= text('commune') ?><select name="commune" id="commune" required disabled><option><?= $lang === 'ar' ? 'اختر الولاية أولاً' : 'Choose a Wilaya first' ?></option></select></label></div><label><?= $lang === 'ar' ? 'طريقة التوصيل' : 'Delivery method' ?><select name="delivery_method"><option <?= $method === 'À domicile' ? 'selected' : '' ?>><?= text('home') ?></option><option <?= $method === 'Bureau' ? 'selected' : '' ?>><?= text('bureau') ?></option></select></label><?php if ($config['recaptcha_site_key'] !== 'YOUR_RECAPTCHA_SITE_KEY'): ?><div class="g-recaptcha" data-sitekey="<?= e($config['recaptcha_site_key']) ?>"></div><?php else: ?><div class="notice">Configure Google reCAPTCHA keys in <code>config.local.php</code> before production.</div><?php endif; ?><div class="summary"><div><span>Subtotal</span><b><?= money($subtotal) ?></b></div><div><span>Delivery</span><b><?= money($shipping) ?></b></div><div class="total"><span>Total</span><b><?= money($subtotal + $shipping) ?></b></div></div><button class="dark" type="submit"><?= text('cod') ?> →</button></form><?php endif; ?></main><script>const locations=<?= json_encode($locations, JSON_UNESCAPED_UNICODE) ?>;const wilaya=document.querySelector('#wilaya');const commune=document.querySelector('#commune');wilaya?.addEventListener('change',()=>{const data=locations[wilaya.value];commune.innerHTML='';(data?.communes||[]).forEach(name=>{const option=document.createElement('option');option.value=name;option.textContent=name;commune.appendChild(option)});commune.disabled=!data});const toggle=document.querySelector('[data-theme-toggle]');const saved=localStorage.getItem('lissi-theme');if(saved)document.documentElement.dataset.theme=saved;toggle?.addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('lissi-theme',next)});</script></body></html>
